public function redact_export_credentials($value) {
    if (!is_array($value)) return is_object($value) ? null : $value;
    $clean = array();
    foreach ($value as $key => $item) {
        $normalized = strtolower(preg_replace('/[^a-z0-9]/i', '', (string) $key));
        if (in_array($normalized, array('user', 'username', 'userlogin', 'login', 'account', 'pass', 'password', 'passwd', 'pwd', 'secret', 'secretkey', 'secretid', 'accesskey', 'accesskeyid', 'accesskeysecret', 'apikey', 'apisecret', 'token', 'authorization', 'cookie', 'cookies', 'headers', 'rawdata', 'autologinwebsite'), true) || preg_match('/(?:password|secret|token|apikey|accesskey)/', $normalized)) continue;
        if ($normalized === 'remotewebsite') {
            $clean[$key] = array();
            foreach ((array) $item as $site_id => $site) {
                if (!is_array($site)) continue;
                $clean[$key][$site_id] = array('title' => isset($site['title']) ? $site['title'] : '', 'type' => isset($site['type']) ? $site['type'] : '');
            }
            continue;
        }
        $clean[$key] = $this->redact_export_credentials($item);
    }
    return $clean;
}
